case 'cone': {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.55, 1.1, 16), m);
  cone.position.y = 0.55;
  // safety stripe / trim ring partway up
  const stripe = new THREE.Mesh(
    new THREE.CylinderGeometry(0.39, 0.45, 0.12, 16),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 })
  );
  stripe.position.y = 0.42;
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.62, 0.08, 16), m.clone());
  base.position.y = 0.04;
  // a star tip makes the wizard variant feel magical
  const tip = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.11),
    new THREE.MeshStandardMaterial({ color: 0xfff0a0, emissive: 0x8a6d00, metalness: 0.5, roughness: 0.25 })
  );
  tip.position.y = 1.16;
  g.add(cone, stripe, base, tip);
  break;
}
